  "eaten.text[2]": { al: "ujku të ha.", en: "The wolf devours you." },
  "eaten.text[3]": { al: "loja mbaroi.", en: "The game is over." },
  "pylliLoop.text[0]": { al: "ti ecën thellë në pyll.", en: "You walk deep into the forest." },
  "pylliLoop.text[1]": { al: "ti je përsëri në pyll.", en: "You are back in the forest." },
  "pylliLoop.text[2]": { al: "natën pemët fshehin hënën dhe yjet: është errët.", en: "At night, the trees hide the moon and stars. It is dark." },
