  "pylliLoop.text[11]": { al: "larg një shpellë nxjerr zjarr.", en: "In the distance, a cave breathes fire." },
  "pylliLoop.text[12]": { al: "një dhelpër dhe një ujk kanë mjaltë.", en: "A fox and a wolf have some honey." },
  "pylliLoop.text[13]": { al: "larg rrinë tre vëllezër.", en: "Three brothers dwell far away." },
  "pylliLoop.text[14]": { al: "një rrugë del nga pylli dhe shkon te ura.", en: "A road leads out of the forest and on to the bridge." },
  "shtojzovalle1.text[0]": { al: "është natë dhe hëna është lart.", en: "It is night, and the moon is high." },
