  "shtojzovalle1.text[2]": { al: "shtojzovallet këndojnë.", en: "The shtojzovalle sing." },
  "shtojzovalle1.text[3]": { al: "vallja është e bukur.", en: "The dance is beautiful." },
  "shtojzovalle1.text[4]": { al: "thonë: shtojzovallet mbajnë fatin e njeriut.", en: "They say the shtojzovalle hold a person's fate." },
  "shtojzovalle2.text[0]": { al: "ti sheh shtojzovallet.", en: "You see the shtojzovalle." },
  "shtojzovalle2.text[1]": { al: "një vajzë është e bukur si hëna.", en: "One maiden is as beautiful as the moon." },
  "shtojzovalle2.text[2]": { al: "por vajza ka lot në sy.", en: "But there are tears in the maiden's eyes." },
  "shtojzovalle2.text[3]": { al: "lotët vrasin.", en: "Her tears are deadly." },
  "shtojzovalle2.text[4]": { al: "thonë: jep këmishën tënde, dhe vajza rri me ty.", en: "They say, “Give her your shirt, and the maiden will stay with you.”" },
