  "shtojzovalleVallja.text[2]": { al: "ti je në valle përsëri.", en: "You are back in the dance." },
  "shtojzovalleLot.text[0]": { al: "ti prek vajzën.", en: "You touch the maiden." },
  "shtojzovalleLot.text[1]": { al: "lotët bien në ty.", en: "Her tears fall upon you." },
  "shtojzovalleLot.text[2]": { al: "loja mbaroi.", en: "The game is over." },
