  "shtojzovalleNuse.text[1]": { al: "një vajzë bëhet një nuse.", en: "A maiden becomes a bride." },
  "shtojzovalleBekim.text[0]": { al: "ti ikën ngadalë.", en: "You move away slowly." },
  "shtojzovalleBekim.text[1]": { al: "shtojzovallet të japin bekim.", en: "The shtojzovalle bestow their blessing on you." },
  "shtojzovalleBekim.text[2]": { al: "ti je i sigurt.", en: "You are safe." },
