  "shtrigaNate.text[1]": { al: "shtriga do gjakun e fëmijës.", en: "The shtriga wants the child's blood." },
  "shtrigaNate.text[2]": { al: "thonë: shtriga ikën nga kripë në zjarr.", en: "They say a shtriga flees from salt cast into the fire." },
